        { en: "refreshment", ipa: "/rɪˈfreʃmənt/", vi: "thức uống giải khát", ex: "Cold drinks are perfect refreshments.", exvi: "Đồ uống lạnh là thức giải khát tuyệt vời.", exs: [{"en":"She offered me a small refreshment after the trip.","vi":"Cô ấy mời tôi một chút đồ giải khát sau chuyến đi."},{"en":"A cup of tea is a nice refreshment in the afternoon.","vi":"Một tách trà là món giải khát tuyệt vời vào buổi chiều."},{"en":"The workers enjoyed a quick refreshment at noon.","vi":"Các công nhân thưởng thức một bữa giải khát nhanh vào buổi trưa."},{"en":"A glass of lemonade is a good refreshment.","vi":"Một ly nước chanh là món giải khát tốt."},{"en":"We stopped for a refreshment during the walk.","vi":"Chúng tôi dừng lại uống giải khát trong lúc đi bộ."}] },
        { en: "leftover", ipa: "/ˈleftoʊvər/", vi: "thức ăn thừa", ex: "I stored the leftovers in the fridge.", exvi: "Tôi cất thức ăn thừa vào tủ lạnh.", exs: [{"en":"We threw the leftover food away this morning.","vi":"Chúng tôi đã vứt đồ ăn thừa đi sáng nay."},{"en":"Do not waste food; eat the leftovers tomorrow.","vi":"Đừng lãng phí thức ăn; hãy ăn đồ ăn thừa vào ngày mai."},{"en":"The leftover rice can be used for frying.","vi":"Cơm thừa có thể dùng để chiên."},{"en":"She turned the leftover meat into a sandwich.","vi":"Cô ấy biến thịt thừa thành một cái bánh mì kẹp."},{"en":"Do not throw the leftover soup away.","vi":"Đừng đổ súp thừa đi."}] },
        { en: "buffet", ipa: "/bəˈfeɪ/", vi: "tiệc tự chọn", ex: "The hotel serves a buffet breakfast.", exvi: "Khách sạn phục vụ bữa sáng tự chọn.", exs: [{"en":"Guests can choose many dishes from the buffet.","vi":"Khách mời có thể chọn nhiều món từ tiệc tự chọn."},{"en":"The buffet at the hotel includes fresh fruit.","vi":"Tiệc tự chọn ở khách sạn có kèm trái cây tươi."},{"en":"We paid one price for the buffet.","vi":"Chúng tôi trả một mức giá cho tiệc tự chọn."},{"en":"The buffet offers salads, pasta, and grilled fish.","vi":"Tiệc tự chọn có salad, mì ống và cá nướng."},{"en":"A buffet is great for large parties.","vi":"Tiệc tự chọn rất tốt cho các bữa tiệc lớn."}] },
        { en: "takeaway", ipa: "/ˈteɪkəweɪ/", vi: "đồ mang đi", ex: "Let us order takeaway tonight.", exvi: "Tối nay chúng ta gọi đồ mang đi nhé.", exs: [{"en":"I bought takeaway because I was too tired to cook.","vi":"Tôi mua đồ mang đi vì tôi quá mệt để nấu ăn."},{"en":"We often get Chinese food as takeaway.","vi":"Chúng tôi thường lấy món Trung Quốc mang về."},{"en":"The takeaway box was still warm.","vi":"Hộp đồ mang đi còn ấm."},{"en":"We picked up takeaway on the way home.","vi":"Chúng tôi mua đồ mang đi trên đường về nhà."},{"en":"Takeaway is convenient when guests come suddenly.","vi":"Đồ mang đi tiện lợi khi khách đến đột xuất."}] },
        { en: "tip", ipa: "/tɪp/", vi: "tiền boa", ex: "Leaving a tip is common there.", exvi: "Để lại tiền boa là điều phổ biến ở đó.", exs: [{"en":"The waiter thanked us for the tip.","vi":"Người phục vụ cảm ơn chúng tôi vì tiền boa."},{"en":"He left a tip on the table after dinner.","vi":"Anh ấy để lại tiền boa trên bàn sau bữa tối."},{"en":"She left a small tip for the server.","vi":"Cô ấy để lại một khoản tiền boa nhỏ cho người phục vụ."},{"en":"A tip of ten percent is usual here.","vi":"Tiền boa mười phần trăm là điều bình thường ở đây."},{"en":"Do not forget to tip the delivery driver.","vi":"Đừng quên boa cho người giao hàng."}] }
