        { en: "browser", ipa: "/ˈbraʊzər/", vi: "trình duyệt", ex: "Open the page in your browser.", exvi: "Mở trang trong trình duyệt của bạn.", exs: [{"en":"My browser crashed while I was reading.","vi":"Trình duyệt của tôi bị sập trong khi tôi đang đọc."},{"en":"Update your browser to see the video.","vi":"Hãy cập nhật trình duyệt để xem video."},{"en":"She changed her default browser yesterday.","vi":"Cô ấy đã đổi trình duyệt mặc định hôm qua."},{"en":"The browser blocked the strange pop-up.","vi":"Trình duyệt đã chặn cửa sổ bật lên kỳ lạ."},{"en":"You can open many tabs in one browser.","vi":"Bạn có thể mở nhiều thẻ trong một trình duyệt."}] },
        { en: "cloud", ipa: "/klaʊd/", vi: "lưu trữ đám mây", ex: "Store files in the cloud.", exvi: "Lưu trữ tệp trên đám mây.", exs: [{"en":"I backed up my photos to the cloud.","vi":"Tôi đã sao lưu ảnh của mình lên đám mây."},{"en":"The cloud keeps our documents safe.","vi":"Đám mây giữ tài liệu của chúng tôi được an toàn."},{"en":"She shares files through the cloud at work.","vi":"Cô ấy chia sẻ tệp qua đám mây khi làm việc."},{"en":"The cloud syncs my notes on every device.","vi":"Đám mây đồng bộ ghi chú của tôi trên mọi thiết bị."},{"en":"Free cloud storage is often very limited.","vi":"Bộ nhớ đám mây miễn phí thường rất hạn chế."}] },
        { en: "database", ipa: "/ˈdeɪtəbeɪs/", vi: "cơ sở dữ liệu", ex: "The database stores user records.", exvi: "Cơ sở dữ liệu lưu trữ hồ sơ người dùng.", exs: [{"en":"Our database holds thousands of customer names.","vi":"Cơ sở dữ liệu của chúng tôi lưu hàng nghìn tên khách hàng."},{"en":"The database crashed during the sale.","vi":"Cơ sở dữ liệu bị sập trong đợt giảm giá."},{"en":"She queries the database for old orders.","vi":"Cô ấy truy vấn cơ sở dữ liệu để tìm các đơn hàng cũ."},{"en":"A backup database keeps the site running.","vi":"Một cơ sở dữ liệu dự phòng giúp trang web vẫn hoạt động."},{"en":"The hospital updated its database yesterday.","vi":"Bệnh viện đã cập nhật cơ sở dữ liệu của mình hôm qua."}] },
        { en: "simulation", ipa: "/ˌsɪmjuˈleɪʃn/", vi: "mô phỏng", ex: "The flight simulation feels real.", exvi: "Mô phỏng chuyến bay cảm giác rất thật.", exs: [{"en":"The driving simulation helped her practice safely.","vi":"Trò mô phỏng lái xe giúp cô ấy luyện tập an toàn."},{"en":"A medical simulation trains young doctors.","vi":"Một cuộc mô phỏng y tế đào tạo các bác sĩ trẻ."},{"en":"The simulation showed the storm in detail.","vi":"Mô phỏng thể hiện cơn bão một cách chi tiết."},{"en":"He scored high in the space simulation.","vi":"Anh ấy đạt điểm cao trong trò mô phỏng không gian."},{"en":"Our team ran a fire simulation this week.","vi":"Nhóm của chúng tôi đã thực hiện một cuộc mô phỏng cháy tuần này."}] },
        { en: "innovation", ipa: "/ˌɪnəˈveɪʃn/", vi: "sự đổi mới", ex: "Innovation drives the tech industry.", exvi: "Sự đổi mới thúc đẩy ngành công nghệ.", exs: [{"en":"Each innovation makes our phones smarter.","vi":"Mỗi sự đổi mới đều khiến điện thoại của chúng ta thông minh hơn."},{"en":"The university supports innovation among students.","vi":"Trường đại học khuyến khích sự đổi mới ở sinh viên."},{"en":"Her idea was a great innovation.","vi":"Ý tưởng của cô ấy là một sự đổi mới tuyệt vời."},{"en":"Innovation needs both time and money.","vi":"Sự đổi mới cần cả thời gian lẫn tiền bạc."},{"en":"The prize rewards innovation in medicine.","vi":"Giải thưởng tôn vinh sự đổi mới trong y học."}] },
        { en: "graphics", ipa: "/ˈɡræfɪks/", vi: "đồ họa", ex: "The game has amazing graphics.", exvi: "Trò chơi có đồ họa tuyệt đẹp.", exs: [{"en":"The graphics look real on this screen.","vi":"Đồ họa trông rất thật trên màn hình này."},{"en":"She studied graphic design to improve her graphics.","vi":"Cô ấy đã học thiết kế đồ họa để cải thiện kỹ năng đồ họa."},{"en":"Poor graphics can ruin a game.","vi":"Đồ họa kém có thể làm hỏng trò chơi."},{"en":"The new laptop handles graphics very well.","vi":"Máy tính xách tay mới xử lý đồ họa rất tốt."},{"en":"He creates graphics for online adverts.","vi":"Anh ấy tạo đồ họa cho quảng cáo trực tuyến."}] },
        { en: "audio", ipa: "/ˈɔːdioʊ/", vi: "âm thanh", ex: "Adjust the audio volume, please.", exvi: "Vui lòng điều chỉnh âm lượng tiếng.", exs: [{"en":"The audio in the film is clear.","vi":"Âm thanh trong bộ phim rất rõ."},{"en":"She edited the audio for her podcast.","vi":"Cô ấy đã chỉnh sửa âm thanh cho podcast."},{"en":"The audio cut out during the call.","vi":"Âm thanh bị mất trong lúc gọi điện."},{"en":"Download the audio to listen on the bus.","vi":"Tải âm thanh xuống để nghe trên xe buýt."},{"en":"Poor audio made the lesson hard to follow.","vi":"Âm thanh kém khiến bài học khó theo dõi."}] },
        { en: "video", ipa: "/ˈvɪdioʊ/", vi: "video", ex: "Watch the video to learn more.", exvi: "Xem video để học thêm.", exs: [{"en":"She recorded a video of her concert.","vi":"Cô ấy đã quay video buổi hòa nhạc của mình."},{"en":"The video takes time to load.","vi":"Video mất thời gian để tải."},{"en":"He shared the video with his family.","vi":"Anh ấy đã chia sẻ video với gia đình."},{"en":"A short video explains the game rules.","vi":"Một video ngắn giải thích luật chơi."},{"en":"My video call worked without problems.","vi":"Cuộc gọi video của tôi hoạt động không gặp vấn đề."}] },
        { en: "virtual", ipa: "/ˈvɜːrtʃuəl/", vi: "ảo, thực tế ảo", ex: "We explored a virtual museum.", exvi: "Chúng tôi khám phá một bảo tàng ảo.", exs: [{"en":"She took a virtual tour of the palace.","vi":"Cô ấy đã tham quan ảo cung điện."},{"en":"Virtual reality games can make you dizzy.","vi":"Trò chơi thực tế ảo có thể khiến bạn chóng mặt."},{"en":"The class met in a virtual room.","vi":"Lớp học gặp nhau trong một phòng ảo."},{"en":"A virtual assistant answered my question.","vi":"Trợ lý ảo đã trả lời câu hỏi của tôi."},{"en":"He attended a virtual meeting from home.","vi":"Anh ấy tham dự một cuộc họp ảo từ nhà."}] }
