        { en: "vocalist", ipa: "/ˈvoʊkəlɪst/", vi: "giọng ca chính", ex: "The vocalist has a powerful voice.", exvi: "Giọng ca chính có chất giọng mạnh mẽ.", exs: [{"en":"The vocalist hit every high note perfectly.","vi":"Giọng ca chính hát trúng mọi nốt cao hoàn hảo."},{"en":"Our band is looking for a new vocalist.","vi":"Ban nhạc của chúng tôi đang tìm một giọng ca chính mới."},{"en":"The vocalist thanked the fans after the show.","vi":"Giọng ca chính cảm ơn người hâm mộ sau buổi diễn."},{"en":"She is the vocalist of a small jazz group.","vi":"Cô ấy là giọng ca chính của một nhóm nhạc jazz nhỏ."},{"en":"That young vocalist writes her own songs too.","vi":"Giọng ca trẻ đó cũng tự viết bài hát."}] }
